SELECT m.id AS "message_id!", mine.seq IS NOT NULL AS "claimed!", EXISTS ( SELECT 1 FROM email_gmail_pending_label_writes newer WHERE newer.message_id = m.id AND newer.provider_label_id = l.label AND newer.seq > mine.seq ) AS "has_newer!", EXISTS ( SELECT 1 FROM email_gmail_pending_label_writes newer WHERE newer.message_id = m.id AND newer.provider_label_id = l.label AND newer.seq > mine.seq AND newer.expires_at > now() ) AS "waits!" FROM unnest($1::uuid[]) AS m(id) CROSS JOIN unnest($3::text[]) AS l(label) LEFT JOIN email_gmail_pending_label_writes mine ON mine.message_id = m.id AND mine.provider_label_id = l.label AND mine.write_id = $2
